import { getAllLogs, getTotalRequests, getAverageDuration } from "~/db";

export const onGet: RequestHandler = async (ev) => {
  const format = ev.query.get("format");

  if (format === "json") {
    const [total_requests, average_duration_ms, logs] = await Promise.all([
      getTotalRequests(),
      getAverageDuration(),
      getAllLogs(),
