    ev.json(200, {
      total_requests,
      average_duration_ms,
      logs,
    });
    return;
  }

  // HTML format
  const [totalRequests, averageDuration, logs] = await Promise.all([
    getTotalRequests(),
    getAverageDuration(),
    getAllLogs(),
  ]);

  const logsHtml = logs
